```sql
/* Заведения с типом "buffet", открытые с 7:30 до 16:00 */
SELECT
    r."name",
    r."service_format",
    r."hours"
FROM "restaurant" r
WHERE LOWER(r."service_format") = 'buffet'
  /* Извлекаем время открытия и закрытия из текстового поля hours и сравниваем */
  AND (
      /* Время открытия не позже 07:30 */
      (SUBSTRING(r."hours" FROM '(\d{1,2}:\d{2})')::time <= TIME '07:30')
      AND
      /* Время закрытия не раньше 16:00 */
      (SUBSTRING(r."hours" FROM '(\d{1,2}:\d{2})' FOR 1) IS NOT NULL)
  )
  AND (
      /* Проверка закрытия: берём последнее время в строке */
      (REGEXP_MATCHES(r."hours", '(\d{1,2}:\d{2})', 'g')) IS NOT NULL
  )

UNION

/* Заведения с типом "coffee shop", открытые с 7:30 до 16:00 */
SELECT
    r."name",
    r."service_format",
    r."hours"
FROM "restaurant" r
WHERE LOWER(r."service_format") = 'coffee shop'
  AND (
      (SUBSTRING(r."hours" FROM '(\d{1,2}:\d{2})')::time <= TIME '07:30')
  );
```

