/* Общее количество больниц */
WITH total_hospitals AS (
    SELECT COUNT(DISTINCT h."hospitalid") AS cnt
    FROM "hospitals" h
),
/* Роли, встречающиеся во всех больницах */
common_roles AS (
    SELECT hmr."roleid"
    FROM "hospitals_medical_roles" hmr
    GROUP BY hmr."roleid"
    HAVING COUNT(DISTINCT hmr."hospitalid") = (SELECT cnt FROM total_hospitals)
)
/* Зарплата для таких ролей */
SELECT mr."salary"
FROM "medicalroles" mr
JOIN common_roles cr ON cr."roleid" = mr."roleid";
