/* Общее количество вакансий */
WITH total_postings AS (
    SELECT COUNT(DISTINCT "id") AS total
    FROM "job_postings"
),
/* Требования, встречающиеся во всех вакансиях */
common_requirements AS (
    SELECT jpr."requirement_id"
    FROM "job_postings_requirements" jpr
    GROUP BY jpr."requirement_id"
    HAVING COUNT(DISTINCT jpr."job_posting_id") = (SELECT total FROM total_postings)
)
/* Типы общих требований */
SELECT r."requirement_type", COUNT(*) AS requirement_count
FROM "requirements" r
JOIN common_requirements cr ON cr."requirement_id" = r."id"
GROUP BY r."requirement_type"
ORDER BY requirement_count DESC;
```

