/* Общее количество уникальных банков */
WITH total_banks AS (
    SELECT COUNT(DISTINCT "bankid") AS cnt
    FROM "banks"
),
/* Количество банков, в которых встречается каждая роль */
role_bank_counts AS (
    SELECT fr."rolename", COUNT(DISTINCT bfr."bankid") AS bank_count
    FROM "financial_roles" fr
    JOIN "banks_financial_roles" bfr ON fr."roleid" = bfr."roleid"
    GROUP BY fr."rolename"
)
/* Роли, присутствующие во всех банках */
SELECT rbc."rolename"
FROM role_bank_counts rbc
CROSS JOIN total_banks tb
WHERE rbc.bank_count = tb.cnt;
```

